SourceCode.Declaration:
/// <summary>
/// MET journal unit conversion
/// </summary>
internal class METJournalUnitConversion
{
    InventDim tempInventDim;
    InventTableModule inventTableModule;
    UnitOfMeasureSymbol wareHouseUnit, inventUnit;
    METInventLocation metInventLocation;
    Qty journalCOnvertedQty;

}

Method.Source:
/// <summary>
/// Get converted Qty CWQty for Item
/// </summary>
/// <param name = "_inventLocation">InventLocation</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_journalQty">Journal qty</param>
/// <returns>Quantity</returns>
public Qty getConvertedQtyCWQtyForItem(InventLocation _inventLocation, ItemId _itemId, Qty _journalQty)
{
    journalCOnvertedQty = _journalQty;
    metInventLocation = METInventLocation::findByInventLocationId(_inventLocation.InventLocationId);
    tempInventDim.InventLocationId = _inventLocation.InventLocationId;
    tempInventDim.InventSiteId     = _inventLocation.InventSiteId;
    wareHouseUnit = METInventLocation::getWarehouseUnit(_itemId, tempInventDim);

    if ((metInventLocation.ExternalWMSUnit == METExtWMSUnit::DefaultPurchaseUnit) ||
        (metInventLocation.ExternalWMSUnit == METExtWMSUnit::DefaultSellUnit))
    {
        if (wareHouseUnit && (wareHouseUnit != this.getInventoryUnit(_itemId)))
        {


            EcoResProductUnitConverter productUnitConverter = EcoResProductUnitConverter::newGivenUnitSymbolsForReleasedProduct(
                                                                        _itemId,
                                                                        tempInventDim.inventDimId,
                                                                        wareHouseUnit,
                                                                        this.getInventoryUnit(_itemId),
                                                                        NoYes::Yes);

            journalCOnvertedQty = productUnitConverter.convertValue(journalCOnvertedQty);
        }
    }

    return journalCOnvertedQty;
}

/// <summary>
/// Get inventory unit
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <returns>UnitOfMeasureSymbol</returns>
public UnitOfMeasureSymbol getInventoryUnit(ItemId _itemId)
{
    select firstonly UnitId from inventTableModule
        where inventTableModule.ItemId      == _itemId
        && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

    if (inventTableModule.UnitId)
    {
        inventUnit = inventTableModule.UnitId;
    }

    return inventUnit;
}

/// <summary>
/// Constructs and returns <c>METJournalUnitConversion</c> object.
/// </summary>
/// <returns> <c>METJournalUnitConversion</c> object. </returns>
public static METJournalUnitConversion construct()
{
    METJournalUnitConversion journalUnitConversion = new METJournalUnitConversion();

    return journalUnitConversion;
}
